
-- Batch 14 (FINAL 24): Set continent + history
UPDATE recipes SET continent = 'North America', history = 'Neiman Marcus Chicken Casserole is a classic American potluck dish that became popular through community cookbooks and recipe-sharing culture. These casserole traditions reflect mid-20th-century American home cooking, where convenient, comforting baked dishes fed families and gatherings.' WHERE slug = 'neiman-marcus-chicken-casserole';

UPDATE recipes SET continent = 'North America', history = 'No-Flour Peanut Butter Cookies are an American baking hack that became popular for being both gluten-free and pantry-friendly. Using peanut butter, sugar, and eggs, they reflect America''s long love of peanut-based desserts and the modern trend toward simplified ingredient lists.' WHERE slug = 'no-flour-peanut-butter-cookies';

UPDATE recipes SET continent = 'North America', history = 'No-Knead Cheddar-Jalapeño Bread builds on the 2006 no-knead bread revolution, adding two iconic American flavors: sharp cheddar and jalapeños. This variation represents the modern American home-baking renaissance, where artisan techniques are combined with bold comfort-food flavors.' WHERE slug = 'no-knead-cheddar-jalapeno-bread';

UPDATE recipes SET continent = 'North America', history = 'Peach-Blueberry Pie celebrates two quintessential American summer fruits. Pie-making traditions in the U.S. grew from European baking, but became uniquely American through regional fruit harvests and the cultural place of pie in family gatherings and holidays.' WHERE slug = 'peach-blueberry-pie';

UPDATE recipes SET continent = 'North America', history = 'Summer Berry Stovetop Crisp is an American fruit dessert that evolved from British crumbles, adapted to New World berries. Crisps became popular in the U.S. during the early 20th century as a simpler alternative to pie, showcasing seasonal fruit with an oat or sugar crumble topping.' WHERE slug = 'summer-berry-stovetop-crisp';

UPDATE recipes SET continent = 'North America', history = 'Sun Gold Tomato Pasta is a modern American seasonal pasta dish celebrating the popularity of sweet Sun Gold cherry tomatoes in home gardens. It reflects the contemporary farm-to-table movement where peak-season produce drives simple, flavor-forward cooking.' WHERE slug = 'sun-gold-tomato-pasta';

UPDATE recipes SET continent = 'North America', history = 'Tomato Soup and Grilled Cheese is one of America''s most iconic comfort-food pairings. This casserole variation reflects the American tradition of reinventing classic combinations into crowd-friendly baked dishes for family dinners and potlucks.' WHERE slug = 'tomato-soup-grilled-cheese-casserole';

UPDATE recipes SET continent = 'North America', history = 'Bang Bang Chicken Bites reflect modern American Asian-fusion cuisine, inspired by spicy-sweet sauces popularized in restaurant chains and online recipe culture. The "bang bang" flavor profile became widely known through contemporary U.S. casual dining trends in the 2000s-2010s.' WHERE slug = 'bang-bang-chicken-bites';

UPDATE recipes SET continent = 'North America', history = 'Soy-Glazed Salmon Bowls are part of the modern American bowl-meal trend, blending Japanese-inspired soy glazes with health-focused meal prep culture. These dishes reflect the globalization of flavors and the rise of balanced, customizable meals in contemporary U.S. cooking.' WHERE slug = 'soy-glazed-salmon-bowls';

UPDATE recipes SET continent = 'North America', history = 'Spicy Cashew Scallion Noodles represent American Asian-fusion pantry cooking, combining chili heat, nutty sauces, and quick noodles. This style is popular in modern U.S. home cooking for its speed and bold flavors influenced by Chinese and Southeast Asian sauces.' WHERE slug = 'spicy-cashew-scallion-noodles';

UPDATE recipes SET continent = 'Asia', history = 'Plov is Uzbekistan''s national dish, a fragrant rice pilaf cooked with lamb, carrots, onions, and spices. With roots in ancient Silk Road trade routes, plov reflects Central Asia''s history as a crossroads of cultures. It is traditionally cooked in a kazan (large cauldron) for weddings and celebrations.' WHERE slug = 'plov-uzbekistan';

UPDATE recipes SET continent = 'South America', history = 'Arepas are a staple of Venezuelan and Colombian cuisine, made from ground cornmeal shaped into patties and cooked on a griddle. Corn has been central to indigenous diets in northern South America for thousands of years, and arepas remain a daily bread and symbol of cultural identity.' WHERE slug = 'arepas-ve';

UPDATE recipes SET continent = 'South America', history = 'Pabellón Criollo is Venezuela''s national dish, combining shredded beef, black beans, rice, and fried plantains. The components reflect the country''s cultural history: European cattle ranching traditions, African and indigenous influences in beans and plantains, and Spanish colonial-era staple foods.' WHERE slug = 'pabellon-criollo';

UPDATE recipes SET continent = 'Asia', history = 'Vietnamese fresh spring rolls (gỏi cuốn) showcase Vietnam''s love of fresh herbs, rice paper, and balanced flavors. Unlike fried rolls, these emphasize lightness and freshness. They are a modern classic served as street food and home cooking, reflecting Vietnam''s culinary philosophy of harmony.' WHERE slug = 'spring-rolls-vn';

UPDATE recipes SET continent = 'Asia', history = 'Vietnamese spring rolls are a defining appetizer in Vietnamese cuisine, pairing rice paper with herbs, vegetables, and protein. They reflect the agricultural abundance of the Mekong and Red River deltas and the Vietnamese emphasis on fresh greens and dipping sauces for balance and contrast.' WHERE slug = 'vietnamese-spring-rolls-vn';

UPDATE recipes SET continent = 'Africa', history = 'Akara are West African bean fritters made from black-eyed peas, deeply rooted in Yoruba cuisine and shared across the region. Sold as street food and eaten for breakfast, akara represents West Africa''s long tradition of legume-based cooking and the cultural importance of portable, protein-rich snacks.' WHERE slug = 'akara-beans-fritters-west-africa';

UPDATE recipes SET continent = 'Africa', history = 'Malva Pudding is a beloved South African dessert—spongy, caramelized, and served warm with custard or cream. Its origins are debated (Dutch/English influences are likely), but it became a uniquely South African comfort dessert, especially popular in Afrikaner and Cape Malay households.' WHERE slug = 'malva-pudding-za';

UPDATE recipes SET continent = 'Africa', history = 'Rooibos tea is a South African herbal infusion made from the Aspalathus linearis plant, indigenous to the Cederberg region. Used for generations by local communities, rooibos became commercially popular in the 20th century and is now a global symbol of South African botanical heritage.' WHERE slug = 'rooibos-za';

UPDATE recipes SET continent = 'Africa', history = 'Ifisashi is a Zambian dish of leafy greens cooked with groundnuts (peanuts), creating a rich, creamy relish. Groundnut sauces are central to Southern and Central African cuisines. This dish reflects Zambia''s tradition of pairing greens with nut-based protein for nourishing everyday meals.' WHERE slug = 'ifisashi-peanut-greens-zambia';

UPDATE recipes SET continent = 'Africa', history = 'Nshima with Kapenta pairs Zambia and Zimbabwe''s staple maize porridge with kapenta—small dried fish from Lake Tanganyika and Lake Kariba. This dish represents the lake-based protein traditions of the region and the everyday meal structure of nshima plus relish.' WHERE slug = 'nshima-kapenta-zambia-zimbabwe';

UPDATE recipes SET continent = 'Africa', history = 'Pweza wa Nazi is a Zanzibari octopus curry cooked in coconut milk, reflecting Zanzibar''s Indian Ocean trade heritage. Coconut, spices, and seafood define Swahili coastal cuisine, and this dish represents the fusion of African, Arab, and Indian influences in Zanzibar''s celebrated food culture.' WHERE slug = 'pweza-wa-nazi-octopus-zanzibar';

UPDATE recipes SET continent = 'Africa', history = 'Muriwo une Dovi is a Zimbabwean dish of leafy greens cooked with peanut butter. This combination reflects the Southern African tradition of enriching vegetables with groundnuts for protein and flavor. It''s a staple relish served with sadza and represents everyday Zimbabwean home cooking.' WHERE slug = 'muriwo-une-dovi-zimbabwe';

UPDATE recipes SET continent = 'Africa', history = 'Roadrunner chicken refers to free-range village chicken in Zimbabwe, prized for its firm texture and deep flavor. Often prepared for guests and special occasions, it represents the pride of rural food traditions and the cultural value placed on naturally raised poultry.' WHERE slug = 'roadrunner-chicken-zimbabwe';

UPDATE recipes SET continent = 'Africa', history = 'Sadza ne Nyama is Zimbabwe''s quintessential meal: sadza (thick maize porridge) served with meat. Sadza is the foundation of Zimbabwean cuisine, and pairing it with nyama reflects the communal tradition of sharing hearty stews and grilled meats at family gatherings.' WHERE slug = 'sadza-ne-nyama-zimbabwe';
